const requiredMetrics = ['revenue','expense','net_result','cash_available'];
const failure = (code) => [{ json: { outcome: 'terminal', failurePayload: { p_document_id: expected.documentId, p_claim_id: claim.claim_id, p_source_etag: expected.sourceEtag, p_status: 'failed', p_rows: [], p_note: code, p_excerpt: null } } }];
try {
  if (!Number.isInteger(statusCode) || statusCode < 200 || statusCode >= 300) return failure('worker_request_failed');
  if (extraction?.schemaVersion !== 'financial-extraction.v1' || extraction?.status !== 'needs_review' || extraction?.publishable !== false) throw new Error('invalid_extraction_contract');
  if (extraction.metadata?.company?.id !== expected.companyId || extraction.metadata?.company?.name !== expected.companyName || extraction.metadata?.document?.id !== expected.documentId || extraction.metadata?.document?.etag !== expected.sourceEtag || extraction.metadata?.document?.fileName !== expected.fileName || extraction.metadata?.periodMonth !== '2026-09') throw new Error('extraction_identity_mismatch');
  const sheets = extraction.metadata?.sheets;
  if (!Array.isArray(sheets) || sheets.length !== requiredSheets.length || requiredSheets.some((name) => !sheets.includes(name))) throw new Error('required_sheet_structure_mismatch');
  if (!Array.isArray(extraction.warnings) || extraction.warnings.some((warning) => warning?.severity === 'error')) throw new Error('extraction_contains_error_warning');
  if (!Array.isArray(extraction.reconciliations) || extraction.reconciliations.some((item) => item?.status === 'failed')) throw new Error('financial_reconciliation_failed');
  if (!Array.isArray(extraction.facts) || !Array.isArray(extraction.bankTransactions)) throw new Error('invalid_extraction_payload');
  const canonical = extraction.facts.filter((fact) => fact?.includedInConsolidatedKpi === true && fact?.aggregationLevel === 'canonical');
  if (canonical.length !== 4 || new Set(canonical.map((fact) => fact.metricCode)).size !== 4 || requiredMetrics.some((metric) => !canonical.some((fact) => fact.metricCode === metric))) throw new Error('missing_or_duplicate_required_canonical_fact');
  const logicalKeys = new Set();
  const rows = canonical.map((fact) => {
    if (!requiredMetrics.includes(fact.metricCode) || fact.companyId !== expected.companyId || fact.companyName !== expected.companyName || fact.documentId !== expected.documentId || fact.sourceEtag !== expected.sourceEtag || fact.periodMonth !== '2026-09' || fact.currency !== 'BRL' || fact.reviewStatus !== 'needs_review' || fact.sourceScope !== 'business') throw new Error('invalid_canonical_fact');
    if (typeof fact.logicalKey !== 'string' || !fact.logicalKey || logicalKeys.has(fact.logicalKey)) throw new Error('invalid_or_duplicate_logical_key');
    logicalKeys.add(fact.logicalKey);
    if (!/^-?\d+\.\d{2}$/.test(fact.amount) || (fact.metricCode !== 'net_result' && fact.amount.startsWith('-'))) throw new Error('invalid_financial_amount');
    const sheet = String(fact.evidence?.sheet ?? '').trim();
    const sourceCell = String(fact.evidence?.cellAddress ?? '');
    const rowMatch = sourceCell.match(/(\d+)$/);
    const sourceRow = rowMatch ? Number(rowMatch[1]) : 0;
    if (!requiredSheets.includes(sheet) || !/^[A-Z]{1,3}[1-9][0-9]*$/.test(sourceCell) || !Number.isSafeInteger(sourceRow) || sourceRow <= 0) throw new Error('invalid_fact_provenance');
    const logicalKey = [expected.documentId, expected.sourceEtag, sheet, sourceCell, fact.metricCode, '2026-09'].join(':');
    if (fact.logicalKey !== logicalKey) throw new Error('logical_key_mismatch');
    return { logical_key: logicalKey, company_id: expected.companyId, company_name: expected.companyName, month: '2026-09-01', metric_code: fact.metricCode, amount: fact.amount, currency: 'BRL', sheet, source_row: sourceRow, source_cell: sourceCell, review_status: 'needs_review' };
  });
  return [{ json: { outcome: 'ready', supportedFactCount: rows.length, deferredFactCount: extraction.facts.length - rows.length, deferredBankTransactionCount: extraction.bankTransactions.length, rpcPayload: { p_document_id: expected.documentId, p_claim_id: claim.claim_id, p_source_etag: expected.sourceEtag, p_status: 'needs_review', p_rows: rows, p_note: 'financial-extraction.v1 canonical facts; manual real pilot 11D', p_excerpt: null } } }];
